  s = ''.join(ch if (ch.isalnum() or ch == ' ') else ' ' for ch in s)
  stop = ['kart','kartım','kartımın','kartımı','kartı','kartını','kartının','kartımla','borcu','borcunu','borcum','olan','benim','lütfen']
  return ' '.join(t for t in s.split() if t not in stop)
def label(c):
  return c['name'] if c['name'] else ('sonu ' + spell(c['last4']) + ' ile biten kartınız')
def names_text(lst):
