    l = label(c)
    if l not in ns:
      ns.append(l)
  if not ns:
    return ''
  if len(ns) == 1:
    return ns[0]
  return ', '.join(ns[:-1]) + ' ve ' + ns[-1]
def dmatch(num, dg):
  num = str(num)
  if len(dg) > len(num):
    return False
  tail = num[len(num) - len(dg):]
