        if num(b, 'transferAmount') > 0:
          transfer.append(cur)
      debt.append(s)
    top = str(d.get('statementPaymentStatus') or '').upper()
    if not debt or top == 'NO_DEBT':
      kind = 'nodebt'
      body = head + 'kartınızın ' + fd(sd) + ' tarihli ekstresinden borcunuz bulunmamaktadır.'
      if tlb is not None and num(tlb, 'totalDebt') > 0:
        body += ' Gelecek dönemler dahil toplam borcunuz ' + ac(num(tlb, 'totalDebt'), 'TL') + '.'
      if lp is not None:
        if today is not None and lp == today:
          body += ' Son ödeme tarihiniz bugündür.'
        else:
          body += ' Son ödeme tarihiniz ' + fd(lp) + ' olacaktır.'
    else:
      debt[0] = head + 'kartınıza ait ' + fd(sd) + ' tarihinde kesilen ekstre ' + debt[0]
      body = ''
      if transfer:
        body = njoin(transfer) + ' borcunuzun bir kısmı Türk Lirası borcunuza aktarılmıştır. '
      body += ' '.join(debt)
      if clear:
        body += ' ' + clear_s(clear)
      body += ' ' + due_s(lp, today)
  body = body.strip()
  try:
    read = json.loads(vars.get('read_indices') or '[]')
  except Exception:
    read = []
  if card and card.get('i') not in read:
    read.append(card.get('i'))
  vars['read_indices'] = json.dumps(read)
  unread = [c for c in cards if c.get('main') and c.get('i') not in read]
  est = str(vars.get('email_state') or '')
  if kind in ('nodebt', 'nostatement'):
    after = MENU
  elif est == 'error':
    after = AGENT
  elif est == 'ok' and sd is not None:
    after = 'Hesap kesim tarihinizi değiştirebilirim ya da ekstrenizi kayıtlı mail adresinize gönderebilirim.'
  else:
    after = 'Hesap kesim tarihinizi değiştirebilirim.'
  vars['offer_text'] = after
  if unread:
    follow = 'Başka bir kartınızın borcunu öğrenmek ister misiniz?'
    route = 'talk'
  else:
    follow = after
    route = 'end' if after in (MENU, AGENT) else 'talk'
  vars['reading_body'] = body
  vars['reading_text'] = body + ' ' + follow
  vars['reading_route'] = route
  vars['statement_date_raw'] = str(d.get('statementDate') or '')
  vars['card_state'] = 'read'
  vars['week_state'] = ''
  vars['change_state'] = ''
  vars['select_candidates'] = vars.get('initial_candidates') or '[]'
  vars['select_fail_count'] = '0'
  vars['balance_state'] = 'ok'
def main():
  try:
    build()
  except Exception:
    vars['balance_state'] = 'error'
try:
  globals().update(locals())
except Exception:
  pass
main()
